<script setup lang="ts">
import {localize} from './localization';

import {computed,ref} from 'vue';
import {useSession} from './store';
import CutAssemblyPreview from './CutAssemblyPreview.vue';
const props=defineProps<{language:'zh'|'en';manufacturing?:boolean}>(),emit=defineEmits<{loaded:[pieceId:string]}>(),store=useSession(),zh=computed(()=>props.language==='zh'),project=computed(()=>store.data.project),entries=computed(()=>[...(project.value?.cuttingLibrary??[])].reverse()),selected=ref(''),search=ref('');
const entry=computed(()=>entries.value.find(e=>e.id===selected.value)??entries.value.find(e=>e.id===project.value?.activeCutId)??entries.value[0]),shown=computed(()=>entries.value.filter(e=>e.name.toLocaleLowerCase().includes(search.value.toLocaleLowerCase())));
async function load(){const p=project.value,e=entry.value;if(!p||!e)return false;const loaded=await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'cutting.activate',entryId:e.id}));if(loaded)emit('loaded',e.run.pieces[0]?.id??'');return loaded;}
async function remove(){const p=project.value,e=entry.value;if(p&&e&&await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'cutting.delete',entryId:e.id})))selected.value='';}
async function exportCut(){if(!await load())return;const p=project.value;if(p&&p.activeCutId===entry.value?.id)await store.run(()=>window.fpcad.patternBundle(p.id,p.revision,'export'));}
</script>
<template><section class="cut-library"><h3>{{zh?'裁切库':localize('Cutting library')}} · {{entries.length}}</h3><p>{{zh?'每次确认裁切都会保存模型、花纹和版型快照。选择历史版本可预览组合，载入会恢复该版模型及裁片（可撤销）。':localize('Each accepted cut saves model, markings and pattern snapshots. Preview an older assembly; loading restores that model and its pieces (undoable).')}}</p><template v-if="entries.length"><input v-model="search" :aria-label="zh?'搜索裁切版本':localize('Search cut versions')" :placeholder="zh?'搜索裁切版本':localize('Search cut versions')"><div class="cut-versions"><button v-for="e in shown" :key="e.id" :class="{active:entry?.id===e.id}" @click="selected=e.id"><strong>{{e.name}}</strong><small>{{new Date(e.createdAt).toLocaleString(zh?'zh-CN':'en-US')}} · {{e.run.pieces.length}} {{zh?'片':localize('pieces')}}{{project?.activeCutId===e.id?(zh?' · 当前制版来源':localize(' · Current source')):''}}</small></button></div><template v-if="entry"><div class="library-actions"><button :disabled="store.busy" @click="load">{{manufacturing?(zh?'从裁切库获取版型':localize('Load patterns from library')):(zh?'载入此裁切版本':localize('Load this cut version'))}}</button><button :disabled="store.busy" @click="exportCut">{{zh?'导出版型文件 ZIP':localize('Export patterns ZIP')}}</button><button :disabled="store.busy||project?.activeCutId===entry.id" @click="remove">{{zh?'删除此历史版本':localize('Delete this version')}}</button></div><details><summary>{{zh?'选择裁片并预览组合':localize('Select cuts and preview assembly')}}</summary><CutAssemblyPreview :key="entry.id" :surface="entry.surface" :run="entry.run" :markings="entry.markings" :language="language"/></details></template></template><p v-else>{{zh?'先完成花纹与裁剪线，再点击裁切并确认版型；制版从这里获取裁片。':localize('Finish markings and cut lines, cut and accept patterns; pattern making loads cuts here.')}}</p></section></template>
<style scoped>.cut-library{padding:15px;border-block:1px solid var(--border)}h3{font-size:13px;margin:0}p{font-size:11px;line-height:1.7;color:var(--text-muted)}.cut-versions{max-height:190px;overflow:auto;margin:8px 0}.cut-versions button{width:100%;text-align:left;display:block;margin:5px 0}.cut-versions button.active{border-color:var(--accent);background:var(--selected)}.cut-versions strong,.cut-versions small{display:block;overflow-wrap:anywhere}.cut-versions small{font-size:10px;margin-top:4px}.library-actions{display:grid;gap:6px}summary{font-size:12px;cursor:pointer;margin-top:12px}</style>
